import{_ as a,o as s,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"离线变化问题","description":"","frontmatter":{"translationSource":{"title":"离线变化问题","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=GjnzRv6BmgC2eu1H5cGJWs","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/changes-caused-by-going-offline"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/changes-caused-by-going-offline"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/changes-caused-by-going-offline"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/changes-caused-by-going-offline"}]]},"headers":[],"relativePath":"zh/changes-caused-by-going-offline.md","filePath":"zh/page-GjnzRv6BmgC2eu1H5cGJWs.md"}'),c={name:"zh/changes-caused-by-going-offline.md"};function t(d,e,r,l,n,p){return s(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="离线变化问题" tabindex="-1">离线变化问题 <a class="header-anchor" href="#离线变化问题" aria-label="Permalink to &quot;离线变化问题&quot;">​</a></h1><blockquote><p>源页面 ID：<code>GjnzRv6BmgC2eu1H5cGJWs</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=GjnzRv6BmgC2eu1H5cGJWs" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>目前已知离线引发的问题：</p><p><span id="source-block-WMbSyPWYK7nw7P4uE58IPH"></span></p><h4 id="准入口降速" tabindex="-1">准入口降速 <a class="header-anchor" href="#准入口降速" aria-label="Permalink to &quot;准入口降速&quot;">​</a></h4><p>关于这一点，目前认为限速越低，受离线影响越小。利用其与其他物流元件做差速\\瞬时优先级可以用于计量离线时长，或者少元件的超低限速结构。</p><p><span id="source-block-WHHUYSpa6DPnVeGB3liEWV"></span></p><h4 id="优先汇入优先级变化" tabindex="-1">优先汇入优先级变化 <a class="header-anchor" href="#优先汇入优先级变化" aria-label="Permalink to &quot;优先汇入优先级变化&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-97d6b4b2ee7eb1df.q90-938ed5cd2eac6d7b.webp" alt="离线变化问题"></p><p>取货口优先级随机变化</p><p><span id="source-block-7vahfYQSDvObfe8VQ0z2fe"></span></p><h4 id="orirock于10月9日晚" tabindex="-1">orirock于10月9日晚 <a class="header-anchor" href="#orirock于10月9日晚" aria-label="Permalink to &quot;orirock于10月9日晚&quot;">​</a></h4><p>下路物流均为最后放置，此外依次四组分别为：后放右侧存货口、复制第一组、后放左侧存货口、复制第三组</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cc696542ac133191.q90-6f764f8f967ceb4e.webp" alt="离线变化问题"></p><p>经过多次离线后，四组状态均不变</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0c56a46ddd414f28.q90-dba10f0f247caaff.webp" alt="离线变化问题"></p><p>重新放置二三组的右侧取货口使其发生迟滞</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b9867200eeb49b55.q90-9d259bbd02f73ade.webp" alt="离线变化问题"></p><p>离线一分钟后，迟滞消失</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3845f1a166f9a361.q90-31feaa94ef7f105e.webp" alt="离线变化问题"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-41c71f6140013347.q90-d9d43f9ae7e9836c.webp" alt="离线变化问题"></p><p>重新一四组放置左侧存货口</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d55f1061158cfa66.q90-6851c7f17caa2f00.webp" alt="离线变化问题"></p><p>离线1分钟后，迟滞未恢复</p><p><span id="source-block-CXTU0b23RZUrPaeTiipGDT"></span></p><h4 id="斯改-10-21-12-07-42" tabindex="-1">斯改: 10-21 12:07:42 <a class="header-anchor" href="#斯改-10-21-12-07-42" aria-label="Permalink to &quot;斯改: 10-21 12:07:42&quot;">​</a></h4><p>高级垃圾桶120以内下线也会出问题，还有人要研究一下吗（</p><p>目前有的猜测：服务器关闭不稳定机器／模拟频率放缓</p></div>',1)])])}const h=a(c,[["render",t]]);export{g as __pageData,h as default};
